using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
partial class TerminalWindow {
 bool trafficMonth=true,trafficLines=true,trafficBars=true,trafficDown=true,trafficUp=true;DateTime trafficDate=DateTime.Today;TrafficChart trafficChart;TextBlock trafficPeriod;DatePicker trafficPicker;Button trafficWeekButton,trafficMonthButton;CheckBox trafficBarCheck,trafficLineCheck;
 void BuildTrafficHistoryPage(){BuildArchivePage();}
 void BuildTrafficHistory(Panel body){trafficSummary=Text("",16);body.Children.Add(trafficSummary);SettingDescription(body,"只统计柯南运行期间当前所选网卡的有效采样，保留最近180个有记录日期。空白日期没有记录，不按0流量补画；不是系统完整用量或运营商账单。");var row=new WrapPanel();body.Children.Add(row);trafficWeekButton=Button(row,"按周",()=>{trafficMonth=false;RefreshTrafficHistory();});trafficMonthButton=Button(row,"按月",()=>{trafficMonth=true;RefreshTrafficHistory();});Button(row,"← 上一期",()=>ShiftTraffic(-1));Button(row,"本期",()=>{trafficDate=DateTime.Today;trafficPicker.SelectedDate=trafficDate;RefreshTrafficHistory();});Button(row,"下一期 →",()=>ShiftTraffic(1));trafficPicker=new DatePicker{SelectedDate=trafficDate,Width=135,Margin=new Thickness(0,5,8,5)};trafficPicker.Resources[typeof(System.Windows.Controls.Primitives.DatePickerTextBox)]=new Style(typeof(System.Windows.Controls.Primitives.DatePickerTextBox),TryFindResource(typeof(TextBox)) as Style);System.Windows.Automation.AutomationProperties.SetName(trafficPicker,"流量日期");row.Children.Add(trafficPicker);trafficPicker.SelectedDateChanged+=(s,e)=>{if(trafficPicker.SelectedDate.HasValue){trafficDate=trafficPicker.SelectedDate.Value;RefreshTrafficHistory();}};trafficBars=assistant.Config.Monitor.ArchiveBars;trafficLines=assistant.Config.Monitor.ArchiveLines;trafficBarCheck=TaskbarCheck(row,"柱状图",trafficBars);trafficLineCheck=TaskbarCheck(row,"折线图",trafficLines);trafficBarCheck.Click+=(s,e)=>{trafficBars=trafficBarCheck.IsChecked==true;SaveMonitor(()=>assistant.Config.Monitor.ArchiveBars=trafficBars);RefreshTrafficHistory();};trafficLineCheck.Click+=(s,e)=>{trafficLines=trafficLineCheck.IsChecked==true;SaveMonitor(()=>assistant.Config.Monitor.ArchiveLines=trafficLines);RefreshTrafficHistory();};var down=TaskbarCheck(row,"下载流量",trafficDown);var up=TaskbarCheck(row,"上传流量",trafficUp);down.Click+=(s,e)=>{trafficDown=down.IsChecked==true;RefreshArchive(true);};up.Click+=(s,e)=>{trafficUp=up.IsChecked==true;RefreshArchive(true);};trafficPeriod=Text("",12);body.Children.Add(trafficPeriod);trafficChart=new TrafficChart();body.Children.Add(new ScrollViewer{Content=trafficChart,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,Margin=new Thickness(0,12,0,8)});Button(body,"导出流量CSV",ExportTraffic);RefreshTrafficHistory();}
 void ShiftTraffic(int delta){trafficDate=trafficMonth?trafficDate.AddMonths(delta):trafficDate.AddDays(7*delta);trafficPicker.SelectedDate=trafficDate;RefreshTrafficHistory();}
 void RefreshTrafficHistory(){if(trafficChart==null)return;TrafficPoint[] points;lock(assistant)points=TrafficHistory.Range(assistant.Config.Monitor.Days,trafficDate,trafficMonth);trafficSummary.Text="本期 ↓ "+TrafficSize(points.Sum(p=>p.Download))+"   ↑ "+TrafficSize(points.Sum(p=>p.Upload));trafficPeriod.Text=points[0].Date.ToString("yyyy-MM-dd")+" — "+points.Last().Date.ToString("yyyy-MM-dd")+" · "+points.Count(p=>p.Recorded)+"天有记录 · 横向滚动查看，悬停显示每日数值";trafficWeekButton.Tag=!trafficMonth?"selected":null;trafficMonthButton.Tag=trafficMonth?"selected":null;trafficChart.Points=points;trafficChart.Lines=trafficLines;trafficChart.Bars=trafficBars;trafficChart.ShowDownload=trafficDown;trafficChart.ShowUpload=trafficUp;trafficChart.MinWidth=Math.Max(650,points.Length*44+70);trafficChart.InvalidateVisual();}
 void ExportTraffic(){using(var picker=new System.Windows.Forms.SaveFileDialog{Filter="CSV文件|*.csv",FileName="柯南流量记录.csv"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){string[] rows;lock(assistant)rows=new[]{"日期,下载字节,上传字节"}.Concat(assistant.Config.Monitor.Days.Select(d=>d.Day+","+d.Download.ToString("F0",System.Globalization.CultureInfo.InvariantCulture)+","+d.Upload.ToString("F0",System.Globalization.CultureInfo.InvariantCulture))).ToArray();System.IO.File.WriteAllLines(picker.FileName,rows,new System.Text.UTF8Encoding(true));}}
}
